r(pg_get_constraintdef(c.oid)) like '%source_type%' and lower(pg_get_constraintdef(c.oid)) like '%source_id%' and lower(pg_get_constraintdef(c.oid)) like '%transfer_group_id%' and lower(pg_get_constraintdef(c.oid)) like '%manual%' and lower(pg_get_constraintdef(c.oid)) like '%customer_payment%' and lower(pg_get_constraintdef(c.oid)) like '%supplier_payment%' and lower(pg_get_constraintdef(c.oid)) like '%transfer%' when 'treasury_transactions_reversal_check' then lower(pg_get_constraintdef(c.oid)) like '%reversed_at%' and lower(pg_get_constraintdef(c.oid)) like '%reversed_by%' and lower(pg_get_constraintdef(c.oid)) like '%reversal_reason%' and lower(pg_get_constraintdef(c.oid)) like '%null%' and lower(pg_get_constraintdef(c.oid)) like '%trim%' else false end))) then 'PASS' else 'BLOCKER' end,8,'All account and transaction CHECK constraints by exact name and normalized semantics'
