 union all select 'INDEXES','structural_catalog',case when (select count(*) from index_catalog where index_name='treasury_transactions_source_unique' and indisunique and columns=array['company_id','source_type','source_id']::text[] and position('source_idisnotnull' in predicate)>0)=1 and (select count(*) from index_catalog where index_name='treasury_transactions_transfer_idx' and not indisunique and columns=array['company_id','transfer_group_id']::text[] and position('transfer_group_idisnotnull' in predicate)>0)=1 and (select count(*) from index_catalog where index_name='treasury_transactions_account_date_idx' and columns=array['company_id','treasury_account_id','transaction_date','created_at']::text[] and desc_flags=array[false,false,true,true])=1 then 'PASS' else 'BLOCKER' end,3,'Structural index columns, predicates and DESC bitmasks; indoption 3 accepted'
 union all select 'REVERSAL','contracts',case when bool_and(passed) then 'PASS' else 'BLOCKER' end,count(*) filter(where not passed), 'Customer, supplier, manual and transfer reversal contracts' from reversal_contracts
 union all select 'COMPATIBILITY','new_and_legacy_acl',case when (select count(*) from expected_functions e join pg_proc p on p.oid=to_regprocedure(e.signature) cross join lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) x where e.internal=false and x.grantee='authenticated'::regrole and x.privilege_type='EXECUTE')=12 and not exists(select 1 from pg_proc p cross join lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) x where p.oid in (to_regprocedure('public.dmp_record_invoice_payment(uuid,numeric,date,text,text,text)'),to_regprocedure('public.dmp_record_supplier_payment(uuid,numeric,date,text,text,text)')) and x.grantee='authenticated'::regrole and x.privilege_type='EXECUTE') then 'PASS' else 'BLOCKER' end,12,'No public legacy create path; treasury-aware functions executable by authenticated'
), summary as (select 'SUMMARY' as check_group,'verify_132_treasury_core' as check_name,case when count(*) filter(where status='BLOCKER')=0 then 'PASS' else 'BLOCKER' end as status,count(*) filter(where status='BLOCKER')::bigint as affected_rows,case when count(*) filter(where status='BLOCKER')=0 then 'Treasury verification passed' else 'Treasury verification failed' end as details from checks)
select check_group,check_name,status,affected_rows,details from (select check_group,check_name,status,affected_rows,details from checks union all select check_group,check_name,status,affected_rows,details from summary) result order by case when check_group='SUMMARY' then 1 else 0 end,check_group,check_name;
